#!/usr/bin/env python3
"""Stream-copy a silent H.264 outro while preserving the body's AAC packets."""

import json
import os
from pathlib import Path
import re
import shutil
import sys
import tempfile

# Do not install or leave generated bytecode beside the portable script pair.
sys.dont_write_bytecode = True
from verify_video import (  # noqa: E402
    ArgumentParser, VideoError, checked_text, input_path, inspect_media,
    new_output_path, print_error, probe_media, remove_owned_file, run_tool,
    verify_video,
)


COMPATIBILITY_FIELDS = ("codec", "width", "height", "fps", "profile", "pixel_format", "time_base")
PACKET_HASH = re.compile(rb"data_hash=SHA256:([0-9a-fA-F]{64})")


def require_compatible(body_info, outro_info):
    if body_info.get("profile") in (None, "unknown", "Unknown", "N/A"):
        raise VideoError("H.264 profile must be available for compatibility checking")
    for field in COMPATIBILITY_FIELDS:
        if body_info[field] != outro_info[field]:
            raise VideoError("Incompatible body/outro " + field + ": " +
                             str(body_info[field]) + " vs " + str(outro_info[field]))


def playlist_quote(path):
    # FFmpeg concat uses single-quote grouping, not Python or shell syntax.
    # End the quoted part, escape a literal apostrophe, then reopen the quote.
    text = checked_text(path, "Concat path")
    return "'" + text.replace("'", "'\\''") + "'"


def audio_packet_hashes(video, ffprobe, destination, temp_dir):
    run_tool(
        ffprobe,
        ["-v", "error", "-select_streams", "a:0", "-show_packets",
         "-show_data_hash", "sha256", "-show_entries", "packet=data_hash:packet_side_data=",
         "-of", "default=noprint_wrappers=1:nokey=0", video],
        "AAC packet hash probe", output=destination, temp_dir=temp_dir,
    )
    destination.seek(0)


def next_packet_hash(source):
    while True:
        line = source.readline(256)
        if not line:
            return None
        if not line.strip():
            continue
        match = PACKET_HASH.fullmatch(line.strip())
        if match is None:
            raise VideoError("AAC packet hash probe returned invalid or unsupported hash output")
        return match.group(1).lower()


def verify_aac_packets(body, merged, ffprobe, temp_dir):
    # Video packet bytes may change when concat inserts necessary SPS/PPS.
    with tempfile.TemporaryFile(dir=temp_dir) as original, tempfile.TemporaryFile(dir=temp_dir) as combined:
        audio_packet_hashes(body, ffprobe, original, temp_dir)
        audio_packet_hashes(merged, ffprobe, combined, temp_dir)
        count = 0
        while True:
            before = next_packet_hash(original)
            after = next_packet_hash(combined)
            if before is None and after is None:
                break
            if before != after:
                raise VideoError("AAC packet hashes/count differ at packet " + str(count + 1))
            count += 1
        if count == 0:
            raise VideoError("Body contains no AAC packets")
        return count


def publish_new_file(source, output):
    # Exclusive creation prevents overwrite even if another process creates the
    # destination after the initial check. On failure delete only our own inode.
    try:
        fd = os.open(output, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    except FileExistsError:
        raise VideoError("Output already exists; refusing to overwrite: " + str(output)) from None
    identity = os.fstat(fd)
    try:
        with os.fdopen(fd, "wb") as destination, source.open("rb") as original:
            shutil.copyfileobj(original, destination, length=1024 * 1024)
            destination.flush()
            os.fsync(destination.fileno())
    except BaseException:
        remove_owned_file(output, identity)
        raise


def merge_outro(body, outro, output, ffmpeg="ffmpeg", ffprobe="ffprobe"):
    body = input_path(body, "Body")
    outro = input_path(outro, "Outro")
    output = new_output_path(output, "Output")
    # All intermediate media, playlists, probe responses and tool diagnostics
    # live in this output-parent directory and are automatically cleaned up.
    with tempfile.TemporaryDirectory(prefix=".merge-outro-", dir=output.parent) as temporary:
        work = Path(temporary)
        body_data = probe_media(body, ffprobe, temp_dir=work)
        outro_data = probe_media(outro, ffprobe, temp_dir=work)
        body_info = inspect_media(body_data)
        outro_info = inspect_media(outro_data)
        if len(body_info["audio"]) != 1:
            raise VideoError("Body must contain exactly one AAC audio stream")
        if outro_info["audio"]:
            raise VideoError("Outro must contain no audio stream; refusing to discard outro audio")
        for label, data in (("Body", body_data), ("Outro", outro_data)):
            if any(stream.get("codec_type") not in ("video", "audio") for stream in data["streams"]):
                raise VideoError(label + " contains additional streams that would be discarded")
        require_compatible(body_info, outro_info)
        expected_frames = body_info["frames"] + outro_info["frames"]
        video_only = work / "body-video.mp4"
        joined_video = work / "joined-video.mp4"
        candidate = work / "validated-output.mp4"
        playlist = work / "concat.txt"
        common = ["-hide_banner", "-v", "error", "-nostdin", "-n"]
        run_tool(
            ffmpeg,
            common + ["-i", body, "-map", "0:v:0", "-c:v", "copy", "-an", "-sn", "-dn",
                      "-f", "mp4", video_only],
            "Extract body video without re-encoding", temp_dir=work,
        )
        # The extracted MP4 must retain the time base/profile needed by concat.
        extracted = inspect_media(probe_media(video_only, ffprobe, temp_dir=work))
        require_compatible(body_info, extracted)
        if extracted["frames"] != body_info["frames"]:
            raise VideoError("Video-only extraction changed the body frame count")
        with playlist.open("x", encoding="utf-8", newline="\n") as manifest:
            manifest.write("file " + playlist_quote(video_only) + "\n")
            manifest.write("file " + playlist_quote(outro) + "\n")
        # Disabling default auto_convert can corrupt the outro's SPS/PPS.
        run_tool(
            ffmpeg,
            common + ["-f", "concat", "-safe", "0", "-i", playlist, "-map", "0:v:0",
                      "-c:v", "copy", "-an", "-sn", "-dn", "-f", "mp4", joined_video],
            "Concatenate video streams without re-encoding", temp_dir=work,
        )
        # No -shortest: body AAC may end before the silent outro does. Copy the
        # ORIGINAL body AAC, not an intermediate, and do not synthesize silence.
        run_tool(
            ffmpeg,
            common + ["-i", joined_video, "-i", body, "-map", "0:v:0", "-map", "1:a:0",
                      "-c", "copy", "-movflags", "+faststart", "-f", "mp4", candidate],
            "Mux original AAC with joined video", temp_dir=work,
        )
        verified = verify_video(
            candidate, ffmpeg, ffprobe, width=body_info["width"], height=body_info["height"],
            fps=body_info["fps"], frames=expected_frames, temp_dir=work,
        )
        require_compatible(body_info, verified)
        if len(verified["audio"]) != 1:
            raise VideoError("Merged output must retain exactly one AAC stream")
        audio_packets = verify_aac_packets(body, candidate, ffprobe, work)
        # Publish only a fully validated file. This final filesystem copy does
        # not run FFmpeg and does not transform the validated media bytes.
        publish_new_file(candidate, output)
    return {
        "ok": True, "output": str(output), "body_frames": body_info["frames"],
        "outro_frames": outro_info["frames"], "frames": verified["frames"],
        "duration_seconds": verified["duration_seconds"], "fps": verified["fps"],
        "decode": "ok", "aac_packet_hashes": "identical",
        "audio_packets_verified": audio_packets, "video_reencoded": False,
    }


def main(argv=None):
    parser = ArgumentParser(description=__doc__)
    parser.add_argument("--body", required=True)
    parser.add_argument("--outro", required=True)
    parser.add_argument("--output", required=True, help="New MP4 output; existing paths are never overwritten")
    parser.add_argument("--ffmpeg", default="ffmpeg")
    parser.add_argument("--ffprobe", default="ffprobe")
    try:
        args = parser.parse_args(argv)
        result = merge_outro(args.body, args.outro, args.output, args.ffmpeg, args.ffprobe)
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except (Exception, KeyboardInterrupt) as exc:
        print_error(exc)
        return 130 if isinstance(exc, KeyboardInterrupt) else 1


if __name__ == "__main__":
    sys.exit(main())
